/**
 * Hides the requests modal by setting its visibility state to false.
 *
 * This action is used to:
 * - Explicitly close the requests modal without toggling
 * - Ensure the modal is closed regardless of its current state
 * - Provide a clean way to close the modal after completing operations
 *
 * Unlike the toggle action, this always sets the modal state to closed,
 * making it safe to call even when the modal state is uncertain.
 */
export const hideRequestsModal = createAction(
  'calendarOverlayingPanels/hideRequestsModal',
);

